import{_ as l,a0 as o,w as r,s as d,ao as t,I as p,x as n,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何在 Bash 中編寫函數 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Bash 中編寫函數 | LCTT (202006) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Bash 中編寫函數 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Bash 中編寫函數 | LCTT (202006) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202006/20200610 How to write functions in Bash","title":"如何在 Bash 中編寫函數","tag":"202006","desc":""},"relativePath":"202006/20200610 How to write functions in Bash.md","filePath":"[post].md"}'),u={name:"202006/20200610 How to write functions in Bash.md"};function h(g,s,b,f,k,m){const a=o("Link");return r(),d("div",null,[s[26]||(s[26]=t(`<h1 id="如何在-bash-中編寫函數" tabindex="-1">如何在 Bash 中編寫函數 <a class="header-anchor" href="#如何在-bash-中編寫函數" aria-label="Permalink to “如何在 Bash 中編寫函數”">​</a></h1><blockquote><p>通過編寫函數來減少代碼的冗餘和維護。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202006/17/125913hf1efce5c48cebrc.jpg" alt=""></p><p>在編程時，實際上是在定義要由計算機執行的<ruby>過程<rt>procedure</rt></ruby>或<ruby>例程<rt>routine</rt></ruby>。一個簡單的類比是將計算機編程與烤麪包進行比較：你一次列出了要組建工作環境的配料，然後列出了烤麪包所必須採取的步驟。在編程和烘烤中，必須以不同的間隔重複執行某些步驟。例如，在烤麪包中，這可能是酵母培養的過程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>STIR=100</span></span>
<span class="line"><span>SNOOZE=86400</span></span>
<span class="line"><span></span></span>
<span class="line"><span>function feed_culture {</span></span>
<span class="line"><span>  remove_from(pantry)</span></span>
<span class="line"><span>  add(flour, water)</span></span>
<span class="line"><span>  stir($STIR)</span></span>
<span class="line"><span>  sleep($SNOOZE)</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>然後，揉麪和醒發麪團：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>KNEAD=600</span></span>
<span class="line"><span>SNOOZE=7200</span></span>
<span class="line"><span></span></span>
<span class="line"><span>function process_dough {</span></span>
<span class="line"><span>  remove_from(proofing_drawer)</span></span>
<span class="line"><span>  knead($KNEAD)</span></span>
<span class="line"><span>  return_to_drawer($SNOOZE)</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在編程中，這些<ruby>子例程<rt>subroutines</rt></ruby>可以表示為<ruby>函數<rt>function</rt></ruby>。函數對程序員很重要，因為它們有助於減少代碼中的冗餘，從而減少了所需的維護量。例如，在以編程方式烤製麪包的假想場景中，如果你需要更改麪糰醒發的用時，只要你之前使用函數，那麼你只需更改一次用時，或使用變量（在示例代碼中為 <code>SNOOZE</code>）或直接在處理麪糰的子程序中更改用時。這樣可以節省你很多時間，因為你不必通過你的代碼庫遍歷每個可能正在醒發的麪糰，更不用説擔心錯過一個。許多 bug 是由未更改的缺失的值或執行不正確的 <code>sed</code> 命令引起的，它們希望捕獲所有可能而不必手動尋找。</p>`,8)),p("p",null,[s[1]||(s[1]=n("在 ",-1)),e(a,{href:"https://opensource.com/resources/what-bash"},{default:i(()=>[...s[0]||(s[0]=[n("Bash",-1)])]),_:1}),s[2]||(s[2]=n(" 中，無論是在編寫的腳本或在獨立的文件中，定義函數和使用它們一樣簡單。如果將函數保存到獨立的文件中。那麼可以將它 ",-1)),s[3]||(s[3]=p("code",null,"source",-1)),s[4]||(s[4]=n(" 到腳本中，就像 ",-1)),s[5]||(s[5]=p("code",null,"include",-1)),s[6]||(s[6]=n(" C 語言或 C++ 中的庫或將模組 ",-1)),s[7]||(s[7]=p("code",null,"import",-1)),s[8]||(s[8]=n(" 到 Python 中一樣。要創建一個 Bash 函數，請使用關鍵字 ",-1)),s[9]||(s[9]=p("code",null,"function",-1)),s[10]||(s[10]=n("：",-1))]),s[27]||(s[27]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>function foo {</span></span>
<span class="line"><span># code here</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>這是一個如何在函數中使用參數的例子（有些人為設計，因此可能會更簡單）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/usr/bin/env bash</span></span>
<span class="line"><span>ARG=$1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>function mimic {</span></span>
<span class="line"><span>  if [[ -z $ARG ]]; then</span></span>
<span class="line"><span>    ARG=&#39;world&#39;</span></span>
<span class="line"><span>  fi</span></span>
<span class="line"><span>  echo &quot;hello $ARG&quot;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>mimic $ARG</span></span></code></pre></div><p>結果如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./mimic</span></span>
<span class="line"><span>hello world</span></span>
<span class="line"><span>$ ./mimic everybody</span></span>
<span class="line"><span>hello everybody</span></span></code></pre></div><p>請注意腳本的最後一行，它會執行該函數。對於編寫腳本的新手來説，這是一個普遍的困惑點：函數不會自動執行。它們作為<em>潛在的</em>例程存在，直到被調用。</p><p>如果沒有調用該函數，那麼函數只是被定義，並且永遠不會運行。</p><p>如果你剛接觸 Bash，請嘗試在包含最後一行的情況下執行示例腳本一次，然後在註釋掉最後一行的情況下再次執行示例腳本。</p><h3 id="使用函數" tabindex="-1">使用函數 <a class="header-anchor" href="#使用函數" aria-label="Permalink to “使用函數”">​</a></h3><p>即使對於簡單的腳本，函數也是很重要的編程概念。你越適應函數，在面對一個不僅需要聲明性的命令列，還需要更多動態的複雜問題時，你就會越容易。將通用函數保存在單獨的文件中還可以節省一些工作，因為它將幫助你建立常用的程序，以便你可以在項目間重用它們。看看你的腳本習慣，看是否適合使用函數。</p><hr>`,11)),p("p",null,[s[12]||(s[12]=n("via: ",-1)),e(a,{href:"https://opensource.com/article/20/6/bash-functions"},{default:i(()=>[...s[11]||(s[11]=[n("https://opensource.com/article/20/6/bash-functions",-1)])]),_:1})]),p("p",null,[s[17]||(s[17]=n("作者：",-1)),e(a,{href:"https://opensource.com/users/seth"},{default:i(()=>[...s[13]||(s[13]=[n("Seth Kenlon",-1)])]),_:1}),s[18]||(s[18]=n(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[14]||(s[14]=[n("lujun9972",-1)])]),_:1}),s[19]||(s[19]=n(" 譯者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:i(()=>[...s[15]||(s[15]=[n("geekpi",-1)])]),_:1}),s[20]||(s[20]=n(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[16]||(s[16]=[n("wxy",-1)])]),_:1})]),p("p",null,[s[23]||(s[23]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[21]||(s[21]=[n("LCTT",-1)])]),_:1}),s[24]||(s[24]=n(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:i(()=>[...s[22]||(s[22]=[n("Linux中國",-1)])]),_:1}),s[25]||(s[25]=n(" 榮譽推出",-1))])])}const C=l(u,[["render",h]]);export{T as __pageData,C as default};
